{
  "name": "opencode-lacuna",
  "version": "0.4.3",
  "description": "OpenCode plugin that lets the model archive parts of its own context and restore them later.",
  "type": "module",
  "license": "MIT",
  "main": "./index.ts",
  "exports": {
    ".": "./index.ts",
    "./tui": "./tui.ts"
  },
  "files": [
    "LICENSE",
    "README.md",
    "index.ts",
    "src",
    "tui.ts"
  ],
  "scripts": {
    "test": "node --test 'test/**/*.test.ts'",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opencode/ai": "^2.2.0",
    "@opencode/plugin": "^2.2.0",
    "effect": "^4.0.1"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.8.0",
    "@opentui/solid": ">=0.8.0",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opencode/theme": "^2.2.0",
    "@opentui/core": "^0.8.0",
    "@opentui/solid": "^0.8.0",
    "@types/node": "^24.0.0",
    "solid-js": "^1.9.12",
    "typescript": "^5.9.0"
  },
  "author": "Trollgeir",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Trollgeir/lacuna.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "context",
    "compression",
    "llm"
  ]
}
